import java.io.*;
import java.util.*;

public class Main {
    static class Edge {
        int to, time, cost;
        Edge(int to, int time, int cost) {
            this.to = to;
            this.time = time;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        int node, cost;
        long time;

        State(int node, int cost, long time) {
            this.node = node;
            this.cost = cost;
            this.time = time;
        }

        public int compareTo(State other) {
            return Long.compare(this.time, other.time);
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int V = fs.nextInt();
        int N = fs.nextInt();
        int M = fs.nextInt();

        ArrayList<Edge>[] adj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int A = fs.nextInt();
            int B = fs.nextInt();
            int T = fs.nextInt();
            int P = fs.nextInt();

            if (P <= V) {
                adj[A].add(new Edge(B, T, P));
                adj[B].add(new Edge(A, T, P));
            }
        }

        int X = fs.nextInt();
        int Y = fs.nextInt();

        final long INF = Long.MAX_VALUE / 4;
        long[][] dist = new long[N + 1][V + 1];

        for (int i = 1; i <= N; i++) {
            Arrays.fill(dist[i], INF);
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        dist[X][0] = 0;
        pq.add(new State(X, 0, 0));

        while (!pq.isEmpty()) {
            State cur = pq.poll();

            if (cur.time != dist[cur.node][cur.cost]) {
                continue;
            }

            if (cur.node == Y) {
                System.out.println(cur.time);
                return;
            }

            for (Edge e : adj[cur.node]) {
                int newCost = cur.cost + e.cost;
                if (newCost <= V) {
                    long newTime = cur.time + e.time;
                    if (newTime < dist[e.to][newCost]) {
                        dist[e.to][newCost] = newTime;
                        pq.add(new State(e.to, newCost, newTime));
                    }
                }
            }
        }

        System.out.println(-1);
    }
}
